uniform float speed : 0.1 .. 3.0 = 1.2;
uniform float spread : 0.02 .. 0.35 = 0.10;
uniform vec3 tint : color = 1.0, 0.15, 0.20;

state fixed ph;
state fixed k;

void update() {
  ph = fract(ph + fixed(dt * speed));
  k = fixed(1.0) / fixed(spread);
}

vec3 shade(Led led) {
  fixed dx = fixed(led.pos.x);
  fixed dz = fixed(led.pos.z);
  fixed r = sqrt(dx * dx + dz * dz);
  fixed front = ph * fixed(0.30);
  fixed d = r - front;
  fixed env = max(fixed(0.0), fixed(1.0) - d * k);
  fixed ring = env * env;
  fixed glow = fixed(0.08) + ring * fixed(0.92);
  return tint * float(glow);
}
